    (test_uuid,'golden-09-01','“요리사”是什么意思？','["厨师","公司职员","老师","医生"]',0,'요리사是厨师，母本代表句为어머니는 요리사세요。','recognition',1,'single_choice',10,'foundation','["词汇","母本§4"]','draft',1,true,'STEP 02','母本 §4'),
