    {"code":"vocabulary","order":2,"accent":"jade","type":"learn","minutes":10,"node":"family-and-work","title":{"zh-CN":"核心词汇","ko-KR":"핵심 어휘"},"nodeTitle":{"zh-CN":"把家人、职业和能力连起来","ko-KR":"가족, 직업과 잘하는 일을 연결하기"},"content":{"lead":{"zh-CN":"按看图认关系或职业、点读原形、跟读搭配、放进身份或活动句的顺序学习；20词音频全部待制作。","ko-KR":"관계와 직업을 확인하고 기본형, 결합과 신분·활동 문장으로 익힙니다. 20개 음원은 제작 대기 중입니다."},"vocabulary":[{"ko":"분","zh":"位（人的敬称）","pos":"依存名词","collocation":"이분은 누구세요?"},{"ko":"가족","zh":"家人、家庭","pos":"名词","collocation":"우리 가족"},{"ko":"가족사진","zh":"家庭照片","pos":"名词","collocation":"제 가족사진"},{"ko":"할아버지","zh":"爷爷、外公","pos":"名词","collocation":"제 할아버지"},{"ko":"할머니","zh":"奶奶、外婆","pos":"名词","collocation":"제 할머니세요"},{"ko":"아버지","zh":"爸爸、父亲","pos":"名词","collocation":"수진 씨의 아버지"},{"ko":"어머니","zh":"妈妈、母亲","pos":"名词","collocation":"제 어머니세요"},{"ko":"부모님","zh":"父母","pos":"名词","collocation":"부모님을 소개하다"},{"ko":"직업","zh":"职业","pos":"名词","collocation":"직업을 말하다"},{"ko":"회사원","zh":"公司职员","pos":"名词","collocation":"회사원이세요"},{"ko":"요리사","zh":"厨师","pos":"名词","collocation":"요리사세요"},{"ko":"선생님","zh":"老师","pos":"名词","collocation":"선생님이세요"},{"ko":"의사","zh":"医生","pos":"名词","collocation":"의사세요"},{"ko":"요리","zh":"料理、做饭","pos":"名词","collocation":"요리를 잘하다"},{"ko":"노래","zh":"歌、唱歌","pos":"名词","collocation":"노래를 잘하다"},{"ko":"운동","zh":"运动","pos":"名词","collocation":"운동을 잘하다／운동하다"},{"ko":"잘하다","zh":"擅长、做得好","pos":"动词","collocation":"요리를 잘하다"},{"ko":"일하다","zh":"工作","pos":"动词","collocation":"식당에서 일하다"},{"ko":"소개하다","zh":"介绍","pos":"动词","collocation":"가족을 소개하다"},{"ko":"사진","zh":"照片","pos":"名词","collocation":"사진을 보다"}],"coach":{"zh-CN":"词义选对并确认朗读整句才完成；点读、图片快说和另说搭配为自主练习。","ko-KR":"뜻 정답과 문장 낭독 확인이 필요하며 듣기와 그림 말하기는 자율 연습입니다."},"nextNode":"respectful-family-forms"}},
    {"code":"grammar","order":3,"accent":"iris","type":"learn","minutes":18,"node":"respectful-family-forms","title":{"zh-CN":"语法讲解","ko-KR":"문법 이해"},"nodeTitle":{"zh-CN":"说清关系、能力、身份和尊敬动作","ko-KR":"관계, 능력, 신분과 높임 동작 말하기"},"content":{"lead":{"zh-CN":"四个工具分别连接所属、评价擅长领域、尊敬地说明身份和描述动作。","ko-KR":"네 도구로 소유, 능력, 신분과 높임 동작을 표현합니다."},"grammarCards":[{"form":"N의 N","function":{"zh-CN":"说明照片所属和人物关系。","ko-KR":"사진의 주인과 사람 관계를 밝힙니다."},"rules":["名词1+의+名词2","의与前项连写","저의常缩为제","首次明确关系时保留의"],"examples":[{"ko":"이 사진은 제 가족사진이에요.","zh":"这张照片是我的家庭照。","audioId":"chapter-09-grammar-01-example-01","audioStatus":"pending"},{"ko":"이분은 수진 씨의 아버지세요?","zh":"这位是秀珍的爸爸吗？","audioId":"chapter-09-grammar-01-example-02","audioStatus":"pending"},{"ko":"유나 씨의 가족사진이에요?","zh":"是有娜的家庭照吗？","audioId":"chapter-09-grammar-01-example-03","audioStatus":"pending"}],"caution":{"zh-CN":"助词의与前面的名词连写。","ko-KR":"조사 의는 앞말에 붙여 씁니다."},"comparison":{"zh-CN":"수진 씨의 아버지明确关系；口语省略形式不作为本课控制书写。","ko-KR":"수진 씨의 아버지는 관계를 분명히 나타냅니다."},"source":{"zh-CN":"母本§5.1；旧电子书页码待人工核对。","ko-KR":"원고 §5.1; 기존 전자책 쪽수는 수동 확인이 필요합니다."}},{"form":"N을/를 잘하다","function":{"zh-CN":"说明家人擅长的事。","ko-KR":"가족이 잘하는 일을 말합니다."},"rules":["有收音领域名词接을","无收音接를","尊敬主体使用잘하세요","잘하다词条合写"],"examples":[{"ko":"어머니는 요리를 잘하세요.","zh":"妈妈很会做饭。","audioId":"chapter-09-grammar-02-example-01","audioStatus":"pending"},{"ko":"네, 어머니는 요리를 아주 잘하세요.","zh":"是的，妈妈很会做饭。","audioId":"chapter-09-grammar-02-example-02","audioStatus":"pending"},{"ko":"어머니는 노래를 잘하세요.","zh":"妈妈很会唱歌。","audioId":"chapter-09-grammar-02-example-03","audioStatus":"pending"}],"caution":{"zh-CN":"控制练习中保留领域名词后的宾格助词。","ko-KR":"통제 연습에서는 목적격 조사를 씁니다."},"comparison":{"zh-CN":"요리를 잘하세요评价能力；요리를 하세요只陈述动作。","ko-KR":"요리를 잘하세요는 능력, 요리를 하세요는 동작입니다."},"source":{"zh-CN":"母本§5.2；旧电子书页码待人工核对。","ko-KR":"원고 §5.2; 기존 전자책 쪽수는 수동 확인이 필요합니다."}},{"form":"N(이)세요","function":{"zh-CN":"尊敬地说明人物关系、身份或职业。","ko-KR":"사람 관계, 신분이나 직업을 높여 말합니다."},"rules":["名词有收音接이세요","无收音接세요","与名词连写","通常不用于抬高自己"],"examples":[{"ko":"아버지는 회사원이세요.","zh":"爸爸是公司职员。","audioId":"chapter-09-grammar-03-example-01","audioStatus":"pending"},{"ko":"제 어머니세요.","zh":"是我妈妈。","audioId":"chapter-09-grammar-03-example-02","audioStatus":"pending"},{"ko":"할아버지는 선생님이세요.","zh":"爷爷是老师。","audioId":"chapter-09-grammar-03-example-03","audioStatus":"pending"}],"caution":{"zh-CN":"自我介绍说저는 학생이에요，不用学生이세요。","ko-KR":"자기소개는 저는 학생이에요라고 합니다."},"comparison":{"zh-CN":"어머니는 선생님이세요含身份敬语；저는 학생이에요是普通礼貌体。","ko-KR":"어머니는 선생님이세요는 높임말이고 저는 학생이에요는 일반 해요체입니다."},"source":{"zh-CN":"母本§5.3；旧电子书页码待人工核对。","ko-KR":"원고 §5.3; 기존 전자책 쪽수는 수동 확인이 필요합니다."}},{"form":"A/V-(으)시-","function":{"zh-CN":"尊敬句中动作或状态的主体。","ko-KR":"문장의 동작·상태 주체를 높입니다."},"rules":["有收音且非ㄹ接으시","无收音或ㄹ收音接시","ㄹ在ㅅ前脱落","本课核心产出使用하다类"],"examples":[{"ko":"어머니는 식당에서 일하세요.","zh":"妈妈在餐厅工作。","audioId":"chapter-09-grammar-04-example-01","audioStatus":"pending"},{"ko":"요리를 아주 잘하세요. 매일 운동하세요.","zh":"很会做饭，每天运动。","audioId":"chapter-09-grammar-04-example-02","audioStatus":"pending"},{"ko":"주말에는 두 분이 공원에서 운동하세요.","zh":"周末两位会在公园运动。","audioId":"chapter-09-grammar-04-example-03","audioStatus":"pending"}],"caution":{"zh-CN":"说自己的动作时通常不用主体敬语抬高自己。","ko-KR":"자기 동작에는 보통 주체 높임을 쓰지 않습니다."},"comparison":{"zh-CN":"일하세요可陈述尊敬对象工作；앉으세요可用于请求，须结合主体判断。","ko-KR":"일하세요는 높임 진술, 앉으세요는 요청일 수 있어 주체와 상황을 봅니다."},"source":{"zh-CN":"母本§5.4；旧电子书页码待人工核对。","ko-KR":"원고 §5.4; 기존 전자책 쪽수는 수동 확인이 필요합니다."}}],"coach":{"zh-CN":"六项填空全部正确才完成；规则口述和扩展变形为自主练习。","ko-KR":"여섯 빈칸을 모두 맞혀야 하며 규칙 설명과 확장 활용은 자율 연습입니다."},"nextNode":"family-talk-builder"}},
    {"code":"patterns","order":4,"accent":"coral","type":"practice","minutes":11,"node":"family-talk-builder","title":{"zh-CN":"句型操练","ko-KR":"문형 연습"},"nodeTitle":{"zh-CN":"从单句替换到完整问答","ko-KR":"문장 바꾸기에서 완전한 문답으로"},"content":{"lead":{"zh-CN":"先替换人物关系、身份职业和能力活动，再按问答与回指排列六个完整话轮。","ko-KR":"관계, 직업과 능력을 바꿔 말한 뒤 문답과 지시 관계에 따라 여섯 말차례를 배열합니다."},"replacementSets":[["제 어머니세요.","제 아버지세요.","제 할머니세요.","민지 씨의 할아버지세요."],["어머니는 요리사세요.","아버지는 회사원이세요.","할아버지는 선생님이세요.","할머니는 의사세요."],["요리를 잘하세요.","노래를 잘하세요.","운동을 잘하세요.","식당에서 일하세요."]],"orderItems":["요리사세요. 식당에서 일하세요.","네, 요리를 아주 잘하세요.","이분은 누구세요?","어머니는 무슨 일을 하세요?","제 어머니세요.","그럼 그 일을 잘하세요?"],"personalFrames":["이분은 제 ___세요.","___는/은 ___(이)세요.","___을/를 잘하세요.／___에서 일하세요."],"coach":{"zh-CN":"六个话轮排序全对才完成；替换、快答和个人表达为自主练习。","ko-KR":"여섯 말차례 배열 정답만 필수이며 바꿔 말하기와 개인 표현은 자율 연습입니다."},"nextNode":"family-photo-talk"}},
    {"code":"dialogue","order":5,"accent":"sky","type":"mission","minutes":13,"node":"family-photo-talk","title":{"zh-CN":"实战对话","ko-KR":"실전 대화"},"nodeTitle":{"zh-CN":"从照片介绍到当面介绍","ko-KR":"사진 소개에서 직접 소개로"},"content":{"lead":{"zh-CN":"主场景介绍照片中的父母，第二场景当面介绍奶奶；音频制作后再整段听和逐句跟读。","ko-KR":"첫 장면은 사진 속 부모님, 두 번째 장면은 할머니를 직접 소개하며 음원은 제작 대기 중입니다."},"dialogueScenes":[{"title":{"zh-CN":"校园社团休息区的家庭照片","ko-KR":"학교 동아리 휴게실의 가족사진"},"people":{"zh-CN":"秀珍与丽娜，同龄社团朋友","ko-KR":"수진과 리나, 또래 동아리 친구"},"purpose":{"zh-CN":"介绍父母关系、职业、能力与活动。","ko-KR":"부모님의 관계, 직업, 능력과 활동을 소개합니다."},"audioId":"chapter-09-dialogue-main","audioStatus":"pending","lines":[{"speaker":"리나","ko":"수진 씨, 이분은 누구세요?","zh":"秀珍，这位是谁？"},{"speaker":"수진","ko":"제 어머니세요.","zh":"是我妈妈。"},{"speaker":"리나","ko":"어머니는 무슨 일을 하세요?","zh":"你妈妈做什么工作？"},{"speaker":"수진","ko":"요리사세요. 식당에서 일하세요.","zh":"是厨师，在餐厅工作。"},{"speaker":"리나","ko":"그럼 그 일을 잘하세요?","zh":"那么，她也擅长那项工作吗？"},{"speaker":"수진","ko":"네, 어머니는 요리를 아주 잘하세요.","zh":"是的，妈妈很会做饭。"},{"speaker":"리나","ko":"이분은 수진 씨의 아버지세요?","zh":"这位是秀珍的爸爸吗？"},{"speaker":"수진","ko":"네, 아버지는 회사원이세요. 운동을 잘하세요.","zh":"是的，爸爸是公司职员，很擅长运动。"}]},{"title":{"zh-CN":"寄宿家庭客厅初见奶奶","ko-KR":"홈스테이 거실에서 할머니를 처음 만남"},"people":{"zh-CN":"智贤、丹尼尔和智贤的奶奶","ko-KR":"지현, 다니엘과 지현의 할머니"},"purpose":{"zh-CN":"介绍奶奶、询问能力并完成初次问候。","ko-KR":"할머니를 소개하고 잘하는 일을 물은 뒤 인사합니다."},"audioId":"chapter-09-dialogue-alt","audioStatus":"pending","lines":[{"speaker":"다니엘","ko":"지현 씨, 이분은 누구세요?","zh":"智贤，这位是谁？"},{"speaker":"지현","ko":"제 할머니세요.","zh":"是我奶奶。"},{"speaker":"다니엘","ko":"할머니는 무엇을 잘하세요?","zh":"奶奶擅长什么？"},{"speaker":"지현","ko":"요리를 아주 잘하세요. 매일 운동하세요.","zh":"很会做饭，每天运动。"},{"speaker":"할머니","ko":"다니엘 씨, 만나서 반가워요.","zh":"丹尼尔，很高兴认识你。"},{"speaker":"다니엘","ko":"저도 만나서 반가워요.","zh":"我也很高兴认识您。"}]}],"coach":{"zh-CN":"事实组合题和人物关系回应题都答对才完成；替换与试录为自主练习。","ko-KR":"사실 문제와 관계 응답을 모두 맞혀야 하며 바꿔 말하기와 시험 녹음은 자율 연습입니다."},"nextNode":"listen-and-introduce"}},
    {"code":"listen_speak","order":6,"accent":"jade","type":"practice","minutes":14,"node":"listen-and-introduce","title":{"zh-CN":"听说任务","ko-KR":"듣기·말하기"},"nodeTitle":{"zh-CN":"听出职业，再介绍自己的两位家人","ko-KR":"직업을 듣고 나의 가족 두 분 소개하기"},"content":{"lead":{"zh-CN":"学生端只显示待制作音频与题面；脚本、答案、停顿和对象键只在服务端。","ko-KR":"학생 화면에는 제작 대기 음원과 문제만 보이며 원고, 정답, 쉼과 객체 키는 서버에만 있습니다."},"listening":{"audioId":"chapter-09-listening-family-job","audioStatus":"pending","question":{"zh-CN":"민지的爷爷从事什么职业？","ko-KR":"민지의 할아버지는 무슨 일을 하세요?"}},"speakingTask":{"duration":"45—60秒","targetSeconds":52,"minimumTurns":8,"maximumTurns":10,"requiredInformation":["至少两位家人或尊敬对象","至少一次身份询问","至少一次N의 N","两项身份或职业","两项能力或日常活动","N(이)세요与-(으)시-各至少两次","自然确认或回应"],"pronunciationScore":false},"coach":{"zh-CN":"音频可播放后听辨正确，并提交满足时长、话轮和七类信息的双角色录音才完成；录音不产生分数。","ko-KR":"음원 재생과 듣기 정답, 시간·말차례·일곱 정보의 두 역할 녹음을 모두 갖추며 녹음에는 점수가 없습니다."},"nextNode":"family-photo-message"}},
    {"code":"read_write","order":7,"accent":"coral","type":"practice","minutes":13,"node":"family-photo-message","title":{"zh-CN":"读写拓展","ko-KR":"읽기·쓰기"},"nodeTitle":{"zh-CN":"读家庭照片消息，写一张介绍卡","ko-KR":"가족사진 메시지를 읽고 소개 카드 쓰기"},"content":{"lead":{"zh-CN":"按照片所属、父亲职业、母亲能力和共同活动读取，再写原创家庭介绍。","ko-KR":"사진의 주인, 아버지 직업, 어머니 능력과 함께 하는 활동을 읽고 새 소개를 씁니다."},"reading":{"title":"가족사진 메시지","lines":["[유나 님이 가족사진을 보냈습니다.]","민지: 유나 씨의 가족사진이에요?","유나: 네, 제 가족사진이에요.","유나: 아버지는 회사원이세요.","유나: 어머니는 노래를 잘하세요.","유나: 주말에는 두 분이 공원에서 운동하세요."]},"writing":{"sentences":"6—7","requirements":["至少两位家人或尊敬对象","照片所属或人物关系","两项身份或职业","两项能力或日常活动","四项本课语言工具"],"frame":"이 사진은 ___ 씨의 가족사진이에요.／제 가족사진이에요. → 이분은 제 ___세요. → ___는/은 ___(이)세요. → ___을/를 잘하세요. → ___에서 일하세요／운동하세요.","rubric":["信息完整","核心语法","敬语主体","格式与可理解度"]},"coach":{"zh-CN":"阅读三题全对，提交6—7句、规定信息齐全的原创介绍并完成四维量规自查。","ko-KR":"읽기 세 문제와 6~7문장, 필수 정보 및 네 기준 자기 점검을 모두 완성합니다."},"nextNode":"can-do-check"}},
    {"code":"review","order":8,"accent":"iris","type":"review","minutes":8,"node":"can-do-check","title":{"zh-CN":"自测与复盘","ko-KR":"자기 점검"},"nodeTitle":{"zh-CN":"我能清楚、得体地介绍两位家人吗？","ko-KR":"가족 두 분을 분명하고 알맞게 소개할 수 있을까요?"},"content":{"lead":{"zh-CN":"自主复习展示不作为强制证据；综合多选与五项自查由合同记录。","ko-KR":"자율 복습은 필수 증거가 아니며 종합 문제와 다섯 점검을 기록합니다."},"canDo":[{"ko":"의로 사진의 주인과 가족 관계를 말할 수 있어요.","zh":"我能用의说明照片所属和家庭关系。"},{"ko":"N을/를 잘하다로 가족이 잘하는 일을 말할 수 있어요.","zh":"我能说明家人擅长的事。"},{"ko":"N(이)세요로 어른의 신분이나 직업을 높여 말할 수 있어요.","zh":"我能尊敬地说明长辈身份或职业。"},{"ko":"-(으)시-를 사용하여 높여 말할 사람의 활동을 말할 수 있어요.","zh":"我能用主体敬语说明尊敬对象的活动。"},{"ko":"두 분 이상을 소개하며 45~60초 동안 8~10턴의 가족사진 대화를 할 수 있어요.","zh":"我能完成介绍至少两位人物的双角色交流。"}],"remediation":[{"reason":"词汇","node":"family-and-work"},{"reason":"语法","node":"respectful-family-forms"},{"reason":"理解","node":"family-photo-talk／listen-and-introduce"},{"reason":"表达","node":"listen-and-introduce"},{"reason":"读写","node":"family-photo-message"}],"chapterTest":"korean-level-one-09","coach":{"zh-CN":"综合多选答对，五项自查全部回应并记录返回节点或none后完成。","ko-KR":"종합 문제 정답과 다섯 점검 및 복습 위치 또는 none 기록이 필요합니다."}}}
  ] $modules$::jsonb) loop
    insert into public.digital_textbook_modules (chapter_id,module_code,sort_order,accent_role,title,description)
    values (chapter_uuid,item->>'code',(item->>'order')::integer,item->>'accent',item->'title',item->'nodeTitle')
    on conflict (chapter_id,module_code) do update set sort_order=excluded.sort_order,accent_role=excluded.accent_role,title=excluded.title,description=excluded.description,updated_at=now()
    returning id into module_uuid;
    insert into public.digital_textbook_nodes (module_id,node_code,node_type,sort_order,estimated_minutes,title,content)
    values (module_uuid,item->>'node',item->>'type',1,(item->>'minutes')::integer,item->'nodeTitle',item->'content')
    on conflict (module_id,node_code) do update set node_type=excluded.node_type,sort_order=1,estimated_minutes=excluded.estimated_minutes,title=excluded.title,content=excluded.content,updated_at=now();
  end loop;

  delete from public.digital_textbook_modules
  where chapter_id=chapter_uuid and module_code not in ('orientation','vocabulary','grammar','patterns','dialogue','listen_speak','read_write','review');

  for item in select value from jsonb_array_elements($activities$
  [
    {"node":"mission-map","sort":1,"key":"orientation-check","type":"single_choice","prompt":{"zh-CN":"丽娜第一次看到秀珍家庭照片中的母亲。哪一句最适合礼貌询问这位长辈是谁？","ko-KR":"리나는 수진의 가족사진에서 어머니를 처음 봅니다. 이분이 누구인지 공손하게 묻는 문장은 무엇이에요?"},"instruction":{"zh-CN":"选择同时询问人物身份并尊敬照片中人物的一句；本题不计分。","ko-KR":"사진 속 인물을 높여 말하면서 누구인지 묻는 문장을 고르세요. 점수에는 포함되지 않습니다."},"options":["이분은 누구세요?","무엇을 잘하세요?","어디에서 일하세요?","얼마예요?"],"config":{"shuffle":true,"showScore":false},"answer":{"kind":"index","value":0},"explanation":{"correct":{"zh-CN":"이분은 누구세요?同时礼貌指人并询问身份。","ko-KR":"이분은 누구세요?는 사람을 높여 누구인지 묻습니다."},"feedback":[{"zh-CN":"先区分人物、能力、地点和价格。","ko-KR":"사람, 능력, 장소와 가격을 구별하세요."},{"zh-CN":"目标句同时需要指人的敬称和“谁”。","ko-KR":"사람 높임말과 누구를 함께 찾으세요."},{"zh-CN":"答案是이분은 누구세요?。","ko-KR":"정답은 이분은 누구세요?입니다."}]}},
    {"node":"family-and-work","sort":1,"key":"vocabulary-check","type":"single_choice","prompt":{"zh-CN":"在어머니는 요리사세요.中，요리사是什么意思？","ko-KR":"어머니는 요리사세요.에서 요리사는 무슨 뜻이에요?"},"instruction":{"zh-CN":"选择词义，再朗读整句一次并勾选确认。","ko-KR":"뜻을 고른 뒤 문장 전체를 읽고 확인하세요."},"options":["公司职员","厨师","老师","医生"],"config":{"shuffle":true,"audioStatus":"pending","readAloudConfirmation":{"type":"checkbox","label":"已朗读整句","required":true}},"answer":{"kind":"index_confirmation","value":1},"explanation":{"correct":{"zh-CN":"요리사是厨师；整句表示妈妈是厨师。","ko-KR":"요리사는 요리를 직업으로 하는 사람입니다."},"feedback":[{"zh-CN":"先看词中的요리。","ko-KR":"요리라는 말을 먼저 보세요."},{"zh-CN":"这是职业名，不是活动本身。","ko-KR":"활동이 아니라 직업 이름입니다."},{"zh-CN":"答案是厨师。","ko-KR":"정답은 요리사입니다."}]}},
    {"node":"respectful-family-forms","sort":1,"key":"grammar-fill","type":"fill_blank","prompt":{"zh-CN":"完成六小题，检查所属、能力领域助词、身份敬语和主体敬语。","ko-KR":"소유, 목적격 조사, 신분 높임말과 주체 높임말 여섯 문항을 완성하세요."},"instruction":{"zh-CN":"按题面指定功能填写；每空只接受本课目标形式。","ko-KR":"문항에 제시된 기능에 맞는 이번 과의 형태를 쓰세요."},"options":[],"config":{"inputMode":"text","normalize":"NFC","shuffle":true,"items":[{"id":"f1","label":"수진 씨___ 아버지（表示所属）","placeholder":"请输入答案"},{"id":"f2","label":"요리___ 잘하세요（填宾格助词）","placeholder":"请输入答案"},{"id":"f3","label":"회사원___（尊敬地说明身份）","placeholder":"请输入答案"},{"id":"f4","label":"의사___（尊敬地说明身份）","placeholder":"请输入答案"},{"id":"f5","label":"어머니는 학교에서 일하다 → 학교에서 ___（尊敬主语）","placeholder":"请输入答案"},{"id":"f6","label":"할머니는 공원에서 운동하다 → 공원에서 ___（尊敬主语）","placeholder":"请输入答案"}]},"answer":{"kind":"text_array","value":["의","를","이세요","세요","일하세요","운동하세요"]},"explanation":{"correct":{"zh-CN":"答案依次为의、를、이세요、세요、일하세요、운동하세요。","ko-KR":"정답은 의, 를, 이세요, 세요, 일하세요, 운동하세요입니다."},"feedback":[{"zh-CN":"先标记所属、宾格、身份或动作。","ko-KR":"소유, 목적격, 신분과 동작을 먼저 구별하세요."},{"zh-CN":"检查名词收音和被尊敬的主体。","ko-KR":"명사 받침과 높이는 주체를 확인하세요."},{"zh-CN":"对照四张语法卡将六题全部正确重做。","ko-KR":"네 문법 카드를 보고 여섯 답을 다시 쓰세요."}]}},
    {"node":"family-talk-builder","sort":1,"key":"pattern-order","type":"ordering","prompt":{"zh-CN":"把六张打乱的完整话轮卡排成语义连贯的对话。","ko-KR":"섞인 여섯 개의 완전한 말차례를 자연스럽게 배열하세요."},"instruction":{"zh-CN":"只根据问答语义、人物指代和话题延续关系拖动。","ko-KR":"질문과 대답, 지시와 화제 연결만 보고 옮기세요."},"options":["요리사세요. 식당에서 일하세요.","네, 요리를 아주 잘하세요.","이분은 누구세요?","어머니는 무슨 일을 하세요?","제 어머니세요.","그럼 그 일을 잘하세요?"],"config":{"shuffle":true,"resetBeforeSubmit":true},"answer":{"kind":"order","value":[2,4,3,0,5,1]},"explanation":{"correct":{"zh-CN":"先问身份并回答关系，再问职业、回答职业，最后以그 일回指并回答能力。","ko-KR":"신분과 관계, 직업, 그 일을 받은 능력 문답 순서입니다."},"feedback":[{"zh-CN":"检查每个问句是否紧跟同类回答。","ko-KR":"질문 뒤에 같은 정보의 답이 오는지 보세요."},{"zh-CN":"그 일必须先有职业内容，네必须回应问题。","ko-KR":"그 일의 앞 내용과 네가 받는 질문을 찾으세요."},{"zh-CN":"正确顺序为第3、5、4、1、6、2张卡。","ko-KR":"정답 순서는 3, 5, 4, 1, 6, 2입니다."}]}},
    {"node":"family-photo-talk","sort":1,"key":"dialogue-fact-check","type":"single_choice","prompt":{"zh-CN":"主场景中，秀珍母亲的职业和父亲擅长的活动分别是什么？","ko-KR":"첫 장면에서 수진의 어머니는 무슨 일을 하고 아버지는 무엇을 잘하세요?"},"instruction":{"zh-CN":"选择母亲职业／父亲擅长活动的正确组合。","ko-KR":"어머니 직업과 아버지가 잘하는 활동의 조합을 고르세요."},"options":["요리사／운동","회사원／요리","선생님／노래","의사／운동"],"config":{"shuffle":true},"answer":{"kind":"index","value":0},"explanation":{"correct":{"zh-CN":"第4轮说母亲是厨师，第8轮说父亲擅长运动。","ko-KR":"4턴은 어머니가 요리사, 8턴은 아버지가 운동을 잘한다고 말합니다."},"feedback":[{"zh-CN":"分别找母亲职业句和父亲能力句。","ko-KR":"어머니 직업과 아버지 능력 문장을 찾으세요."},{"zh-CN":"不要交换两人的信息。","ko-KR":"두 사람의 정보를 바꾸지 마세요."},{"zh-CN":"正确组合是요리사／운동。","ko-KR":"정답은 요리사／운동입니다."}]}},
    {"node":"family-photo-talk","sort":2,"key":"dialogue-response","type":"single_choice","prompt":{"zh-CN":"朋友指着家庭照片问이분은 누구세요?，哪一句能直接、得体地说明人物关系？","ko-KR":"친구가 가족사진을 가리키며 이분은 누구세요?라고 물었습니다. 알맞은 관계 응답은 무엇이에요?"},"instruction":{"zh-CN":"选择能回答是谁并对长辈使用身份敬语的一句。","ko-KR":"누구인지 답하고 어른을 높여 말하는 문장을 고르세요."},"options":["제 어머니세요.","요리를 잘하세요.","식당에서 일하세요.","사진을 봐요."],"config":{"shuffle":true},"answer":{"kind":"index","value":0},"explanation":{"correct":{"zh-CN":"제 어머니세요直接说明人物关系并使用身份敬语。","ko-KR":"제 어머니세요는 관계를 직접 높여 말합니다."},"feedback":[{"zh-CN":"排除只说能力、地点或看照片的句子。","ko-KR":"능력, 장소나 사진 보기 문장을 빼세요."},{"zh-CN":"答案需要家庭关系名词和身份敬语。","ko-KR":"가족 관계 명사와 신분 높임말이 필요합니다."},{"zh-CN":"答案是제 어머니세요。","ko-KR":"정답은 제 어머니세요입니다."}]}},
    {"node":"listen-and-introduce","sort":1,"key":"listening-family-job","type":"listening","prompt":{"zh-CN":"听家庭照片语音说明，判断민지的爷爷从事什么职业。","ko-KR":"가족사진 음성 소개를 듣고 민지의 할아버지 직업을 고르세요."},"instruction":{"zh-CN":"正常语速最多两遍，慢速最多一遍；只依据身份句作答。","ko-KR":"보통 속도 두 번, 느린 속도 한 번 듣고 신분 문장에 근거해 답하세요."},"options":["선생님","의사","요리사","회사원"],"config":{"audioId":"chapter-09-listening-family-job","audioStatus":"pending","normalReplayLimit":2,"slowReplayLimit":1,"shuffle":true},"answer":{"kind":"index","value":0},"transcript":"이 사진은 제 가족사진이에요. 이분은 제 할아버지세요. 할아버지는 선생님이세요. 학교에서 일하세요. 노래를 잘하세요.","audioObjectKey":"korean-level-one/chapter-09/listening/chapter-09-listening-family-job.mp3","audioStatus":"pending","explanation":{"correct":{"zh-CN":"原文明确说爷爷是老师。","ko-KR":"원고는 할아버지가 선생님이라고 말합니다."},"feedback":[{"zh-CN":"再听할아버지는后的身份名词。","ko-KR":"할아버지는 뒤의 신분 명사를 들으세요."},{"zh-CN":"学校是辅助线索，直接依据仍是身份句。","ko-KR":"학교는 단서이며 신분 문장이 직접 근거입니다."},{"zh-CN":"答案是선생님。","ko-KR":"정답은 선생님입니다."}],"privateListening":{"slowScript":"이 사진은 제 가족사진이에요. / 이분은 제 할아버지세요. / 할아버지는 선생님이세요. / 학교에서 일하세요. / 노래를 잘하세요.","pauseMarks":"이 사진은 제 가족사진이에요. ⏸ 이분은 제 할아버지세요. ⏸ 할아버지는 선생님이세요. ⏸ 학교에서 일하세요. ⏸ 노래를 잘하세요.","speaker":"F05／민지；第一人称语音说明","distractorReasons":{"1":"原文没有医生信息。","2":"不要带入主对话母亲的职业。","3":"原文没有公司职员信息。"}}}},
    {"node":"listen-and-introduce","sort":2,"key":"speaking-family-introduction","type":"speaking","prompt":{"zh-CN":"完成一段介绍至少两位家人的45—60秒、8—10轮双角色家庭照片交流。","ko-KR":"가족 두 분 이상을 소개하는 45~60초, 8~10턴의 두 역할 대화를 완성하세요."},"instruction":{"zh-CN":"加入身份询问、所属、两项身份或职业、两项能力或活动、两类敬语和自然收束。","ko-KR":"신분 질문, 소유, 두 직업과 활동, 두 높임말과 자연스러운 마무리를 넣으세요."},"options":[],"config":{"minimumSeconds":45,"maximumSeconds":60,"minimumTurns":8,"maximumTurns":10,"requiredCriteria":7,"enforceCompletionRequirements":true,"pronunciationScore":false,"criteria":["至少两位家人或尊敬对象","至少一次身份询问","至少一次N의 N","两项身份或职业","两项能力或日常活动","N(이)세요与-(으)시-各至少两次","自然确认或回应"]},"answer":{"kind":"open"},"explanation":{"correct":{"zh-CN":"已保存满足提交条件的录音完成证据；不产生正确性或分数。","ko-KR":"제출 조건을 갖춘 녹음 완료 증거를 정오나 점수 없이 저장했습니다."},"feedback":[{"zh-CN":"先检查两个角色、8—10轮和至少两位人物。","ko-KR":"두 역할, 8~10턴과 두 분 이상을 확인하세요."},{"zh-CN":"再检查所属、职业、活动和两类敬语。","ko-KR":"소유, 직업, 활동과 두 높임말을 확인하세요."},{"zh-CN":"按七项清单补齐后重录；不显示虚假发音分数。","ko-KR":"일곱 항목을 보완해 다시 녹음하며 발음 점수는 표시하지 않습니다."}]}},
    {"node":"family-photo-message","sort":1,"key":"reading-family-message","type":"single_choice","prompt":{"zh-CN":"阅读家庭照片消息，完成人物所属、父亲职业和母亲能力三题。","ko-KR":"가족사진 메시지를 읽고 사진 주인, 아버지 직업과 어머니 능력 세 문제에 답하세요."},"instruction":{"zh-CN":"每题只选一个答案；答案都能从聊天原句直接找到。","ko-KR":"문제마다 하나를 고르고 공개된 메시지에서 근거를 찾으세요."},"options":[],"config":{"reading":"[유나 님이 가족사진을 보냈습니다.]\n민지: 유나 씨의 가족사진이에요?\n유나: 네, 제 가족사진이에요.\n유나: 아버지는 회사원이세요.\n유나: 어머니는 노래를 잘하세요.\n유나: 주말에는 두 분이 공원에서 운동하세요.","items":[{"id":"q1","question":"누구의 가족사진이에요?","options":["유나 씨","민지 씨","수진 씨","다니엘 씨"]},{"id":"q2","question":"유나 씨의 아버지는 무슨 일을 하세요?","options":["선생님","요리사","회사원","의사"]},{"id":"q3","question":"어머니는 무엇을 잘하세요?","options":["요리","운동","노래","사진"]}],"shuffle":true,"shuffleOptions":true},"answer":{"kind":"index_array","value":[0,2,2]},"explanation":{"correct":{"zh-CN":"答案依次是유나 씨、회사원、노래。","ko-KR":"정답은 유나 씨, 회사원, 노래입니다."},"feedback":[{"zh-CN":"圈出照片确认、父亲身份和母亲能力三句。","ko-KR":"사진 확인, 아버지 신분과 어머니 능력 문장을 찾으세요."},{"zh-CN":"不要带入主对话或听力人物信息。","ko-KR":"다른 대화나 듣기 정보를 섞지 마세요."},{"zh-CN":"依据公开消息将三题全部正确重做。","ko-KR":"메시지에 근거해 세 문제를 다시 푸세요."}]}},
    {"node":"family-photo-message","sort":2,"key":"write-family-introduction","type":"writing","prompt":{"zh-CN":"为同龄朋友写一张介绍至少两位家人的6—7句原创家庭照片卡。","ko-KR":"친구에게 가족 두 분 이상을 소개하는 6~7문장의 글을 쓰세요."},"instruction":{"zh-CN":"包含所属或关系、两项身份或职业、两项能力或活动和四项本课工具，并完成量规自查。","ko-KR":"소유나 관계, 두 직업과 활동, 네 표현을 넣고 기준을 점검하세요."},"options":[],"config":{"minSentences":6,"maxSentences":7,"minimumHangulCharacters":55,"minimumPhraseGroups":4,"requiredPhraseGroups":[["의 가족사진","제 가족사진","우리 가족사진"],["을 잘하세요","를 잘하세요"],["이세요","세요"],["에서 일하세요","운동하세요","공부하세요","요리하세요"]],"minimumInformationKinds":5,"requireCompletionChecklist":true,"informationChecklist":["至少两位家人或尊敬对象","照片所属或人物关系","两项身份或职业","两项能力或日常活动","四项本课语言工具"],"structureFrame":"이 사진은 ___ 씨의 가족사진이에요.／제 가족사진이에요. → 이분은 제 ___세요. → ___는/은 ___(이)세요. → ___을/를 잘하세요. → ___에서 일하세요／운동하세요.","rubric":["信息完整","核心语法","敬语主体","格式与可理解度"],"rubricConfirmation":"我已按四维量规完成自查"},"answer":{"kind":"open"},"explanation":{"correct":{"zh-CN":"已保存满足句数、规定信息和量规自查的原创介绍；不产生正确性或分数。","ko-KR":"문장 수, 필수 정보와 자기 점검을 갖춘 소개를 정오나 점수 없이 저장했습니다."},"feedback":[{"zh-CN":"先数人物、句子和规定信息。","ko-KR":"사람, 문장과 필수 정보를 먼저 세세요."},{"zh-CN":"检查四项工具和尊敬主体。","ko-KR":"네 표현과 높이는 주체를 확인하세요."},{"zh-CN":"按支架补齐缺项，但不要复制示范。","ko-KR":"틀로 빠진 부분을 보완하되 예시를 베끼지 마세요."}]}},
    {"node":"can-do-check","sort":1,"key":"review-multiple","type":"multiple_choice","prompt":{"zh-CN":"选择所有形式正确、人物关系也得体的句子。","ko-KR":"형태가 맞고 사람 관계에도 알맞은 문장을 모두 고르세요."},"instruction":{"zh-CN":"正确项全部选中且不多选才算完成。","ko-KR":"맞는 표현을 모두 고르고 틀린 표현은 고르지 마세요."},"options":["제 어머니세요.（介绍自己的母亲）","어머니는 요리를 잘하세요.（说明母亲的能力）","아버지는 회사원이세요.（说明父亲的职业）","저는 학생이세요.（介绍自己）","수진 씨의 아버지세요?（确认人物关系）"],"config":{"selection":"multiple","shuffle":true},"answer":{"kind":"indices","value":[0,1,2,4]},"explanation":{"correct":{"zh-CN":"除自我介绍使用이세요外，其余四句形式与人物关系得体。","ko-KR":"자기소개에 이세요를 쓴 문장 외 네 문장이 맞습니다."},"feedback":[{"zh-CN":"逐句找被说明的人，判断是不是说话人自己。","ko-KR":"설명하는 사람이 화자 자신인지 보세요."},{"zh-CN":"有一句把身份敬语用于自我介绍。","ko-KR":"한 문장은 자기소개에 높임말을 썼습니다."},{"zh-CN":"正确项是第1、2、3、5句。","ko-KR":"정답은 1, 2, 3, 5번입니다."}]}},
    {"node":"can-do-check","sort":2,"key":"self-check","type":"self_check","prompt":{"zh-CN":"根据实际表现完成五项Can-do自查，并确定下一步复习位置。","ko-KR":"실제 수행을 바탕으로 다섯 Can-do를 점검하고 다음 복습 위치를 정하세요."},"instruction":{"zh-CN":"五项都要回应；有复习项至少选一个返回节点，全部能完成时选择none。","ko-KR":"다섯 항목에 답하고 복습이 필요하면 노드를, 모두 가능하면 none을 고르세요."},"options":[],"config":{"requiredChecks":5,"items":[{"id":"ownership","label":"我能用의说明照片所属和家庭关系／의로 사진 주인과 가족 관계를 말할 수 있어요"},{"id":"ability","label":"我能说明家人擅长的事／가족이 잘하는 일을 말할 수 있어요"},{"id":"identity","label":"我能尊敬地说明长辈身份或职业／어른의 신분이나 직업을 높여 말할 수 있어요"},{"id":"subjectHonorific","label":"我能用主体敬语说明活动／주체 높임말로 활동을 말할 수 있어요"},{"id":"dialogue","label":"我能完成45—60秒、8—10轮家庭照片交流／45~60초, 8~10턴의 가족사진 대화를 할 수 있어요"}],"returnNodes":[{"value":"family-and-work","label":"词汇"},{"value":"respectful-family-forms","label":"语法"},{"value":"family-photo-talk","label":"对话理解"},{"value":"listen-and-introduce","label":"听说"},{"value":"family-photo-message","label":"读写"},{"value":"none","label":"无错／保持练习"}]},"answer":{"kind":"open"},"explanation":{"correct":{"zh-CN":"五项自查与返回位置已保存；不替代其他证据，也不产生分数。","ko-KR":"다섯 점검과 복습 위치를 정오나 점수 없이 저장했습니다."},"feedback":[{"zh-CN":"逐项回想所属、能力、身份、主体敬语和完整交流。","ko-KR":"소유, 능력, 신분, 주체 높임과 대화를 돌아보세요."},{"zh-CN":"把需要复习对应到具体节点。","ko-KR":"복습 필요를 구체적인 노드에 연결하세요."},{"zh-CN":"五项均须作答；有复习项时不能只选none。","ko-KR":"복습 항목이 있으면 none만 고를 수 없습니다."}]}}
  ] $activities$::jsonb) loop
    select node.id into node_uuid from public.digital_textbook_nodes node
    join public.digital_textbook_modules module on module.id=node.module_id
    where module.chapter_id=chapter_uuid and node.node_code=item->>'node';
    if node_uuid is null then raise exception 'Missing chapter 09 node %',item->>'node'; end if;
    insert into public.digital_textbook_activities (node_id,activity_key,activity_type,sort_order,prompt,instruction,options,public_config,max_attempts,counts_toward_completion)
    values (node_uuid,item->>'key',item->>'type',(item->>'sort')::integer,item->'prompt',item->'instruction',item->'options',item->'config',3,true)
    on conflict (node_id,activity_key) do update set activity_type=excluded.activity_type,sort_order=excluded.sort_order,prompt=excluded.prompt,instruction=excluded.instruction,options=excluded.options,public_config=excluded.public_config,max_attempts=3,counts_toward_completion=true,updated_at=now()
    returning id into activity_uuid;
    insert into public.digital_textbook_activity_secrets (activity_id,answer_key,explanation,transcript_ko,audio_object_key,audio_status)
    values (activity_uuid,item->'answer',item->'explanation',item->>'transcript',item->>'audioObjectKey',coalesce(item->>'audioStatus','pending'))
    on conflict (activity_id) do update set answer_key=excluded.answer_key,explanation=excluded.explanation,transcript_ko=excluded.transcript_ko,audio_object_key=excluded.audio_object_key,audio_status=excluded.audio_status,updated_at=now();
  end loop;

  delete from public.digital_textbook_activities activity
  using public.digital_textbook_nodes node,public.digital_textbook_modules module
  where activity.node_id=node.id and node.module_id=module.id and module.chapter_id=chapter_uuid
    and activity.activity_key not in ('orientation-check','vocabulary-check','grammar-fill','pattern-order','dialogue-fact-check','dialogue-response','listening-family-job','speaking-family-introduction','reading-family-message','write-family-introduction','review-multiple','self-check');

  delete from public.digital_textbook_media_assets media
  using public.digital_textbook_nodes node,public.digital_textbook_modules module
  where media.node_id=node.id and node.module_id=module.id and module.chapter_id=chapter_uuid;

  for item in select value from jsonb_array_elements($images$
